using System.Reflection;
using System.Text.Json;
using CardGame.Core;
using CardGame.Content.Standard;
using static BoundaryLiDianChecks;
internal static class BoundaryHuaXiongChecks
{
    const string Skill="boundary:shizhan-current",Binding="selected-actor-duel",Yao="boundary:yaowu-current";
    static int FailSequence;
    public static void ActualDuelAndNullification()
    {
        var(g,r)=Start(completed:true);var hp=g.State.Players[0].Hp;var hand=g.State.Players[0].HandCount;Use(g,1);Cold(g,r);Evidence(g,"duel-issued");Reach(g,p=>p.SkillPrompt?.SkillId=="fixture:hx-completed");Cold(g,r);Evidence(g,"completed-damage-child");Activate(g);Settle(g);
        var declared=g.Events.Select(e=>e.Payload).OfType<CardUseDeclaredEvent>().Single(e=>e.CardKind==CardKind.Duel);
        Require(declared.SourceSeat==1&&declared.CardId==0&&g.State.Players[0].Hp==hp-1&&g.State.Players[0].HandCount==hand+2,"Other selected actor really Uses zero-entity Duel and owner takes non-red damage/Draw.");
        Require(g.Events.Select(e=>e.Payload).OfType<CardUseFinishedEvent>().Count(e=>e.CardKind==CardKind.Duel)==1&&!g.ResolutionStack.OfType<ProgramSkillFrame>().Any(),"Actual Duel completion returns to its Program once.");Cold(g,r);Evidence(g,"duel-finished");
        var(n,nr)=Start(kind:"nullification",jizhi:true,completed:true);Use(n,1);Reach(n,p=>p.Kind==DecisionKind.Nullification&&p.PlayerSeat==0);Cold(n,nr);Evidence(n,"nullification");var physical=P(n)!.Choices.First(c=>c.Cards.Count==1).Cards.Single();Answer(n,c=>c.Cards.SequenceEqual([physical]));while(P(n) is {Kind:DecisionKind.Nullification,PlayerSeat:0})Answer(n,c=>c.Cards.Count==0);Reach(n,p=>p.SkillPrompt?.SkillId=="fixture:hx-completed");Cold(n,nr);Evidence(n,"completed-nullified-child");Skip(n);Settle(n);Require(n.Events.Select(e=>e.Payload).OfType<ProgramBindingStartedEvent>().Any(e=>e.SkillId=="classic:jizhi"),"Actual zero-entity Duel reaches native classic Jizhi actor trigger.");
        Require(!n.Events.Select(e=>e.Payload).OfType<DamageAppliedEvent>().Any()&&n.Events.Select(e=>e.Payload).OfType<CardUseFinishedEvent>().Any(e=>e.CardKind==CardKind.Duel),"Real Nullification prevents the forced Duel then typed parent completes.");
        Require(n.CardMovements.Count(m=>m.CardId==physical&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.Processing)==1,"Actual Nullification entity pays once.");Cold(n,nr);Evidence(n,"nullified-finished");
    }
    static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    static void Skip(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");
    static void Answer(GameEngine g,Func<PromptChoice,bool> choose){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(choose).Id,g.Revision));}
    static void Reach(GameEngine g,Func<PendingDecision,bool> goal){for(var i=0;i<100;i++){if(P(g)is{}p&&goal(p))return;Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("No requested prompt: "+P(g)?.Prompt);}
    static IEnumerable<LegalAction> Actions(GameEngine g)=>g.GetHumanLegalActions().Where(a=>a.ProgramSkillId==Skill);
    static void Use(GameEngine g,int actor)=>Accept(g,new UseProgramSkillCommand(0,Skill,Binding,[],[actor],g.Revision,P(g)!.PromptId));
    static void Driver(GameEngine g,string id,int[]?targets=null)=>Accept(g,new UseProgramSkillCommand(0,"fixture:hx-driver",id,[],targets??[],g.Revision,P(g)!.PromptId));
    static CharacterState[] Players(GameEngine g)=>((IReadOnlyList<CharacterState>)typeof(GameEngine).GetField("_players",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(g)!).ToArray();
    static void Settle(GameEngine g){for(var i=0;i<100;i++){if(P(g)is{Kind:DecisionKind.PlayCard,PlayerSeat:0} && !g.ResolutionStack.Any(f=>f is CardUseFrame or ProgramSkillFrame) || g.State.Status==EngineStatus.Completed)return;if(P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip")==true)Skip(g);else if(P(g) is{PlayerSeat:0,Kind:DecisionKind.RespondSlash or DecisionKind.Nullification or DecisionKind.RescueDying})Answer(g,c=>c.Cards.Count==0);else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Did not settle: "+P(g)?.Prompt);}
    static void Cold(GameEngine g,ContentRegistry r){var cp=g.CreateCheckpoint();var x=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(cp)),r);Require(x.Revision==g.Revision&&JsonSerializer.Serialize(x.CreateCheckpoint().Commands)==JsonSerializer.Serialize(cp.Commands),"Cold accepted commands are identical.");for(var i=0;i<4;i++)Require(JsonSerializer.Serialize(x.CreateSnapshot(i))==JsonSerializer.Serialize(g.CreateSnapshot(i)),"Cold four viewer projections match.");}
    static void Accept(GameEngine g,GameCommand command){var before=GameCheckpointJson.Serialize(g.CreateCheckpoint());try{var x=g.Submit(command);Require(x.Accepted,x.Error?.Message??"Rejected.");}catch(Exception ex){if(Environment.GetEnvironmentVariable("CARD_HX_EVIDENCE") is{Length:>0} root){var d=Path.Combine(root,"actual-submit-"+(++FailSequence));Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"checkpoint-before.json"),before);File.WriteAllText(Path.Combine(d,"attempt.json"),JsonSerializer.Serialize(command,command.GetType()));File.WriteAllText(Path.Combine(d,"post-failure-observed-stack.json"),JsonSerializer.Serialize(g.ResolutionStack));File.WriteAllText(Path.Combine(d,"exception.txt"),ex.ToString());}throw;}}
    static void Evidence(GameEngine g,string label){if(Environment.GetEnvironmentVariable("CARD_HX_EVIDENCE") is not{Length:>0}root)return;var d=Path.Combine(root,label);Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"checkpoint.json"),GameCheckpointJson.Serialize(g.CreateCheckpoint()));File.WriteAllText(Path.Combine(d,"trusted-stack.json"),JsonSerializer.Serialize(g.ResolutionStack));for(var i=0;i<4;i++)File.WriteAllText(Path.Combine(d,"view-"+i+".json"),JsonSerializer.Serialize(g.CreateSnapshot(i)));}
    static void Reject(string members){var rejected=false;try{Load("fixture:hx-bad",members);}catch(InvalidOperationException){rejected=true;}Require(rejected,"Malformed new resource/activation rejects during load.");}
    static SkillProgram Load(string id,string members)=>SkillProgramCatalog.Load("{\"schemaVersion\":"+SkillProgramCatalog.RulesSchemaVersion+",\"skills\":[{\"id\":\""+id+"\",\"revision\":1,"+members+"}]}","{\"schemaVersion\":3,\"skills\":{\""+id+"\":{\"name\":\"fixture\",\"description\":\"fixture\"}}}").Programs[id];
    static string Act(string id,string effects,int targets=0)=>"{\"id\":\""+id+"\",\"minCards\":0,\"maxCards\":0,\"minTargets\":"+targets+",\"maxTargets\":"+targets+",\"targetKind\":\"anyLiving\",\"usesPerTurn\":null,\"effects\":"+effects+"}";
    static(GameEngine,ContentRegistry) Start(string kind="dodge",bool black=false,bool gain=false,int hp=6,bool jizhi=false,bool kongcheng=false,bool extra=false,bool native=false,bool actorBan=false,bool gainDying=false,bool completed=false,bool hongyan=false)
    {var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(kind,black,gain,hp,jizhi,kongcheng,extra,native,actorBan,gainDying,completed,hongyan));var g=GameEngine.CreateStandard(new GameOptions{Seed=31,PlayerCount=4,HumanSeat=native?3:0,HumanRole=native?Role.Rebel:Role.Lord,ModeId="identity:classic-hx",UseInteractiveSetup=!native,AdvanceAfterHumanCommands=false,MaxTurns=5,UseInteractiveDiscard=false},r);Accept(g,new StartGameCommand());if(!native){Reach(g,p=>p.Kind==DecisionKind.SelectGeneral);Accept(g,new SelectGeneralCommand(0,"fixture:hx",g.Revision,P(g)!.PromptId));Settle(g);if(hp==1){Driver(g,"lower");Settle(g);}}return(g,r);}
    sealed class Fixture(string kind,bool black,bool gain,int hp,bool jizhi,bool kongcheng,bool extra,bool native,bool actorBan,bool gainDying,bool completed,bool hongyan):IGameContentPackage
    {
        public PackageManifest Manifest{get;}=new("fixture-hx",new(1,0,0),[]);
        public void Register(IContentRegistryBuilder b)
        {
            try{CharacterFixtureContent.Register(b, "boundary:hua-xiong");}catch(TargetInvocationException ex){throw new InvalidOperationException(ex.InnerException?.ToString(),ex.InnerException);}
            var classic=ContentRegistry.Build(new StandardContentPackage(),new StandardActiveSkillExpansionPackage(true),new StandardRescueSkillExpansionPackage(),new StandardClassicGeneralPackage());
            if(hongyan)b.AddSkill(classic.GetSkill("classic:hongyan"));if(jizhi)b.AddSkill(classic.GetSkill("classic:jizhi"));if(kongcheng)b.AddSkill(classic.GetSkill("classic:kongcheng"));if(extra)b.AddSkill(classic.GetSkill("classic:dangxian"));
            var driver=Act("lower","[{\"op\":\"loseHp\",\"target\":\"owner\",\"amount\":1}]")+","+Act("cardless","[{\"op\":\"damage\",\"target\":\"owner\",\"sourceRef\":{\"kind\":\"selectedTarget\"},\"amount\":1}]",1)+","+Act("legacy-duel","[{\"op\":\"startVirtualDuel\",\"target\":\"owner\"}]",2)+","+Act("empty","[{\"op\":\"discardOwnedZoneCards\",\"target\":\"owner\",\"zones\":[\"hand\"]}]")+","+Act("ban","[{\"op\":\"grantTurnCardActionProhibition\",\"target\":\"owner\",\"cardKinds\":[\"duel\"],\"actionTypes\":[\"use\"]}]",1);
            b.AddSkill(new("fixture:hx-driver","driver","driver"){Program=Load("fixture:hx-driver","\"activations\":["+driver+"]")});
            if(gain)b.AddSkill(new("fixture:hx-gain","gain","gain"){Program=Load("fixture:hx-gain","\"triggers\":[{\"id\":\"gain\",\"window\":\"cardsGained\",\"subject\":\"owner\",\"destinationZones\":[\"hand\"],\"movementOccurrence\":\"perBatch\",\"usageScope\":\"turn\",\"usageLimit\":1,\"optional\":true,\"effects\":[{\"op\":\"selectOwnedCards\",\"target\":\"owner\",\"zones\":[\"hand\"],\"amount\":1,\"resultBind\":\"selected\"},{\"op\":\"moveBoundCards\",\"target\":\"owner\",\"sourceBind\":\"selected\",\"destination\":\"discardPile\"}"+(gainDying?",{\"op\":\"loseHp\",\"target\":\"owner\",\"amount\":1}":"")+"]}]")});
            if(gainDying)b.AddSkill(new("fixture:hx-hp","hp","hp"){Program=Load("fixture:hx-hp","\"triggers\":[{\"id\":\"pause\",\"window\":\"afterHpRecovered\",\"subject\":\"owner\",\"optional\":true,\"usageScope\":\"turn\",\"usageLimit\":1,\"effects\":[{\"op\":\"draw\",\"target\":\"owner\",\"amount\":1}]}]")});
            if(completed)b.AddSkill(new("fixture:hx-completed","completed","completed"){Program=Load("fixture:hx-completed","\"triggers\":[{\"id\":\"pause\",\"window\":\"cardUseCompleted\",\"ownerRelation\":\"target\",\"cardKinds\":[\"duel\"],\"optional\":true,\"effects\":[{\"op\":\"draw\",\"target\":\"owner\",\"amount\":1}]}]")});
            if(jizhi)b.AddSkill(new("fixture:hx-no-counter","no counter","no counter"){Program=Load("fixture:hx-no-counter", "\"triggers\":[{\"id\":\"ban\",\"window\":\"playPhaseStarting\",\"subject\":\"owner\",\"turnOwnerScope\":\"otherLiving\",\"optional\":false,\"effects\":[{\"op\":\"grantTurnCardActionProhibition\",\"target\":\"owner\",\"cardKinds\":[\"nullification\"],\"actionTypes\":[\"use\"]}]}]")});
            if(actorBan)b.AddSkill(new("fixture:hx-ban","ban","ban"){Program=Load("fixture:hx-ban", "\"triggers\":[{\"id\":\"ban\",\"window\":\"playPhaseStarting\",\"subject\":\"owner\",\"turnOwnerScope\":\"otherLiving\",\"optional\":false,\"effects\":[{\"op\":\"grantTurnCardActionProhibition\",\"target\":\"owner\",\"cardKinds\":[\"duel\"],\"actionTypes\":[\"use\"]}]}]")});
            var extras=new[]{Yao}.Concat(hongyan?["classic:hongyan"]:Array.Empty<string>()).Concat(gainDying?["fixture:hx-hp"]:Array.Empty<string>()).Concat(completed?["fixture:hx-completed"]:Array.Empty<string>()).Concat(!native?["fixture:hx-driver"]:Array.Empty<string>()).Concat(gain?["fixture:hx-gain"]:Array.Empty<string>()).Concat(kongcheng?["classic:kongcheng"]:Array.Empty<string>()).Concat(extra?["classic:dangxian"]:Array.Empty<string>()).ToArray();
            b.AddGeneral(new("fixture:hx","华雄","supporter",Skill,"qun",hp,extras,GeneralGender.Male){InitialHp=hp});
            for(var i=1;i<4;i++)b.AddGeneral(new("fixture:hx-"+i,"其他"+i,"supporter",native?Skill:"standard:none","wei",6,new[]{Yao}.Concat(actorBan&&i==1?["fixture:hx-ban"]:Array.Empty<string>()).Concat(jizhi?["classic:jizhi","fixture:hx-no-counter"]:Array.Empty<string>()).ToArray()));
            b.AddDeck(new("fixture:hx-deck","固定",4,0,[]){PhysicalCards=Enumerable.Range(0,96).Select(i=>new ContentDeckPhysicalCard("standard:"+kind,kind=="lightning"&&i==55?Suit.Spade:black?Suit.Spade:Suit.Heart,i%13+1)).ToArray()});
            b.AddMode(new("identity:classic-hx","固定",4,4,new Dictionary<string,int>{{nameof(Role.Lord),1},{nameof(Role.Loyalist),1},{nameof(Role.Rebel),2}},"fixture:hx-deck",GeneralCandidateCount:4,GeneralPoolIds:["fixture:hx","fixture:hx-1","fixture:hx-2","fixture:hx-3"]));
        }
    }
}
